INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch11$PT128-S2-Q7$batch11$, 128, 2, 7, $batch11$Weaken$batch11$, $batch11$Builder: Within ten years, most of the new homes constructed in North America will have steel frameworks rather than wood ones. After all, two-by-fours and two-by-sixes—the sizes of lumber most commonly used in home construction—are deteriorating in quality and increasing in cost, while environment-friendly steel is decreasing in cost. In addition, unlike wood, steel will not warp, rot, or split.$batch11$, $batch11$Which one of the following, if true, most seriously weakens the builder's reasoning?$batch11$, $batch11$D$batch11$, true, $batch11$Batch 11; question text from local bank.$batch11$ FROM lr_sections s WHERE s.preptest=128 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT128-S2-Q7$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$A$batch11$, $batch11$Over the next ten years, labor costs in the home construction industry are expected to rise significantly.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT128-S2-Q7$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$A$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$B$batch11$, $batch11$Steel-framed homes do not have to be treated with pesticides or other chemicals that can contribute to indoor air pollution.$batch11$, $batch11$Strengthener$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT128-S2-Q7$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$B$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$C$batch11$, $batch11$Because lumber prices have increased over the last decade, currently most new homes are built with steel frameworks.$batch11$, $batch11$Strengthener$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT128-S2-Q7$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$C$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$D$batch11$, $batch11$Training home construction workers to work with steel is very costly.$batch11$, $batch11$Correct$batch11$, true FROM lr_questions q WHERE q.qid=$batch11$PT128-S2-Q7$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$D$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$E$batch11$, $batch11$The number of houses built each year is expected to decrease over the next decade.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT128-S2-Q7$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$E$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT128-S2-Q7$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Conclusion$batch11$, $batch11$Within ten years, most new North American homes will have steel frames instead of wood.$batch11$), (1, $batch11$Evidence$batch11$, $batch11$Common lumber is getting worse and costlier, while steel is getting cheaper. Steel won't warp, rot, or split.$batch11$), (2, $batch11$Evaluate$batch11$, $batch11$The builder only compares the materials. Building a home costs more than materials. If switching to steel brings a big new cost, builders might stick with wood.$batch11$), (3, $batch11$Goal$batch11$, $batch11$Find a cost of switching to steel that the builder ignored.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT128-S2-Q7$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$Rising labor costs hit wood and steel homes alike.$batch11$), ($batch11$B$batch11$, $batch11$Another advantage of steel.$batch11$), ($batch11$C$batch11$, $batch11$If most homes already use steel, it is even more likely most will in ten years.$batch11$), ($batch11$D$batch11$, $batch11$Training workers to use steel is very costly. That cost could outweigh steel's savings and keep builders using wood.$batch11$), ($batch11$E$batch11$, $batch11$Fewer homes overall doesn't change the share built with steel.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT128-S2-Q7$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
